/* NEW DRAFTS · Production · web, part C (8 Sep 2026): samples (board, deployed reading, new sample, lifecycle with free
   moves, receive a move, make product), costing, karigars (list, ledger, verification, new karigar, analytics), the
   locked state for roles without Production, and the board registration for the whole module. */

/* ── W23–W25 · Samples ── */
const SAMPLE_TABS = [['In designing', 4], ['Deployed, no production', 3], ['Activated', 1], ['Production started', 1]];
const SampleBar = ({ T, right, on }) => <PBar T={T} right={right}><T.Chip icon="search" outline>Sample no, category, karigar</T.Chip><Caret T={T}>Newest activity</Caret>{['Price TBD', 'Costing pending', 'High growth', '15-day read'].map((c, i) => <T.Chip key={c} on={i === on} outline={i !== on} x={i === on}>{c}</T.Chip>)}<AllFilters T={T} /><OutBtn T={T} small icon="plus">New sample</OutBtn></PBar>;
function SampleCardW({ T, s, on }) {
  return <div className="press" style={{ borderRadius: 18, overflow: 'hidden', background: T.surface, border: `1px solid ${on ? T.accentLine : T.line}`, boxShadow: on ? `0 0 0 2px ${T.accentSoft}` : 'none', minWidth: 0 }}>
    <div style={{ position: 'relative', height: 190, background: T.photoBg }}>{s.d.src ? <img src={s.d.src} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} /> : <span style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', fontFamily: T.fontUI, fontSize: 12, color: T.ink3 }}>No photo yet · add a sketch</span>}<span style={{ position: 'absolute', top: 8, left: 8, display: 'flex', gap: 4 }}><T.PhotoTag>Sample</T.PhotoTag>{s.chips.includes('High growth') && <T.PhotoTag>High growth</T.PhotoTag>}</span>{s.read && <span style={{ position: 'absolute', right: 8, top: 8 }}><ReadRing T={T} n={s.read} size={30} /></span>}</div>
    <div style={{ padding: '9px 11px 11px' }}>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}><span style={{ whiteSpace: 'nowrap' }}><Num T={T} size={19}>{s.no}</Num></span><Meta T={T} style={{ minWidth: 0 }}>{s.cat}</Meta><span style={{ flex: 1 }} /><span style={{ fontFamily: T.fontSerif, fontSize: 14, color: T.ink3 }}>{s.target ? prMoney(s.target) : 'TBD'}</span></div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 4 }}>{s.colours.map(c => <Dot key={c} n={c} />)}<Meta T={T}>{s.moves} moves · since {s.started.slice(0, 5)}</Meta></div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 6 }}><Ic name="map-pin" size={12} color={T.ink3} /><Meta T={T} style={{ flex: 1, color: T.ink2 }}>{s.where}</Meta>{s.chips.filter(c => c !== 'High growth').slice(0, 1).map(c => <Pill key={c} T={T} tone={c.startsWith('Reading') ? 'blue' : 'warn'} small>{c}</Pill>)}</div>
    </div>
  </div>;
}
const SampleMovesPane = ({ T }) => <PPane style={{ padding: '10px 12px 12px' }}><div style={{ display: 'flex', gap: 10 }}><Thumb T={T} d={PR_D('4566')} w={48} h={60} r={11} /><span style={{ flex: 1 }}><Num T={T} size={20}>S-0412</Num><Meta T={T} style={{ display: 'block' }}>Lehenga · cape · Blush · target ₹12,995</Meta><Meta T={T} style={{ display: 'block', marginTop: 2, color: T.ink2 }}>cost so far ₹4,120 · money roles</Meta></span></div><div style={{ marginTop: 10, display: 'grid', gap: 6 }}>{PR_MOVES.map(mv => <div key={mv.n} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 8px', borderRadius: 10, background: T.surface2, fontFamily: T.fontUI, fontSize: 12 }}><span style={{ width: 18, height: 18, borderRadius: 9, background: T.ink, color: T.bg, display: 'grid', placeItems: 'center', fontSize: 10, fontWeight: 600 }}>{mv.n}</span><span style={{ flex: 1 }}>{mv.proc} · {prK(mv.k).name.split(' ')[0]}</span><Pill T={T} tone={mv.back ? 'ok' : 'blue'} small>{mv.back ? 'back' : 'out'}</Pill></div>)}</div><Sect T={T}>References</Sect><div style={{ display: 'flex', gap: 6 }}>{['Pinterest board', 'client photo'].map(r => <span key={r} className="press" style={{ flex: 1, height: 56, borderRadius: 10, background: T.chipBg, display: 'grid', placeItems: 'center', fontFamily: T.fontUI, fontSize: 11, color: T.ink2 }}>{r}</span>)}</div><span style={{ flex: 1 }} /><T.Btn small icon="chevron-right" style={{ height: 34 }}>Open sample</T.Btn></PPane>;
function WebPSamples({ T }) {
  return <PShell T={T} section="Samples" active="Samples" crumb={['Production', 'Samples', 'In designing']} paneTitle="S-0412 · moves" pane={<SampleMovesPane T={T} />} paneWidth={290}>
    <ViewTabs T={T} tabs={SAMPLE_TABS} active="In designing" />
    <PMain>
      <SampleBar T={T} right={<Meta T={T}>9 samples · 4 in designing · 3 on their 15-day read</Meta>} />
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0,1fr))', gap: 12 }}>{PR_SAMPLES.filter(s => s.tab === 'In designing').map((s, i) => <SampleCardW key={s.no} T={T} s={s} on={i === 0} />)}</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 12, fontFamily: T.fontUI, fontSize: 11.5, color: T.ink2 }}><Ic name="info" size={13} color={T.ink3} />A sample moves freely: any process, any order, any karigar, any material. When the piece is right it is deployed to the Catalogue for a 15-day reading; high growth turns it into a product and a first production order.</div>
    </PMain>
  </PShell>;
}
