function WebPKarigarAnalytics({ T }) {
  const ks = PR_KARIGARS.slice(0, 6);
  return <PShell T={T} section="Karigars" active="Karigars" crumb={['Production', 'Karigars', 'Analytics']} paneTitle="Saleem Creation" pane={<KarigarPane T={T} k={prK('k2')} />} paneWidth={300}>
    <ViewTabs T={T} tabs={KAR_TABS} active="Analytics" right={<PTabs T={T} tabs={['30 d', '90 d', 'FY']} on="90 d" />} />
    <PMain>
      <div style={{ display: 'flex', gap: 10 }}><T.Kpi label="On-time tranches" value="76 %" sub="of 118 · 90 d" /><T.Kpi label="Avg days late" value="3.4" sub="when late" tone="danger" /><T.Kpi label="Pcs received" value="4,120" sub="90 d · 27 karigars" /><T.Kpi label="Rejections" value="1.8 %" sub="rework rate" /><T.Kpi label="Material with karigars" value="₹3.1L" sub="at cost · money roles" /></div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginTop: 12 }}>
        <PCard T={T}><Sect T={T} style={{ margin: '0 0 8px' }} right={<Meta T={T}>% of tranches met · 90 d</Meta>}>Reliability by karigar</Sect><BarsV T={T} data={ks.map(k => k.onTime)} labels={ks.map(k => k.name.split(' ')[0])} w={380} h={120} color={T.blue} /></PCard>
        <PCard T={T}><Sect T={T} style={{ margin: '0 0 8px' }} right={<Meta T={T}>pcs per day vs capacity</Meta>}>Load this week</Sect>{ks.map(k => { const load = Math.round(k.cap * (k.jobs >= 6 ? 1.15 : k.jobs >= 4 ? .8 : .45)); return <div key={k.id} style={{ display: 'flex', alignItems: 'center', gap: 8, height: 26, fontFamily: T.fontUI, fontSize: 12 }}><span style={{ width: 90, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{k.name.split(' ')[0]}</span><span style={{ flex: 1, height: 8, borderRadius: 4, background: T.line, overflow: 'hidden' }}><span style={{ display: 'block', width: Math.min(100, load / k.cap * 100) + '%', height: 8, background: load > k.cap ? T.danger : T.blue }} /></span><Meta T={T} style={{ width: 70, textAlign: 'right' }}>{load} / {k.cap}</Meta></div>; })}</PCard>
        <PCard T={T}><Sect T={T} style={{ margin: '0 0 8px' }} right={<Meta T={T}>weekly · all karigars</Meta>}>Pieces received</Sect><LineG T={T} series={[{ pts: [280, 310, 260, 340, 360, 330, 390, 370, 410, 380, 420, 400], color: T.accent, width: 2 }]} w={380} h={90} area /></PCard>
        <PCard T={T}><Sect T={T} style={{ margin: '0 0 8px' }} right={<Meta T={T}>why tranches slipped · 90 d</Meta>}>Delay reasons</Sect><div style={{ display: 'flex', gap: 14, alignItems: 'center' }}><Donut T={T} parts={[{ v: 38, color: T.danger }, { v: 27, color: T.warn }, { v: 20, color: T.blue }, { v: 15, color: T.line2 }]} size={96} thick={14} center="28" /><Legend T={T} items={[['Material short', T.danger, '38 %'], ['Karigar late', T.warn, '27 %'], ['Previous job late', T.blue, '20 %'], ['Rework', T.line2, '15 %']]} /></div></PCard>
      </div>
    </PMain>
  </PShell>;
}

